package net.officefloor.hq.app.asof;

import java.sql.DatabaseMetaData;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/**
 * Every row a sheet holds, kept as its today moves on (sheet_snapshot), so the sheet can be shown as it stood at the
 * end of a date. The tables kept are found on boot: every table with a sheet column (the sheet table by its id) and
 * every table of rows kept per person (a person_id column); each gets a shadow table {@code <table>__ASOF} with the
 * same columns (bar the generated ones) and a snapshot_id. A table added later is kept with no change here.
 */
@Repository
public class SheetSnapshots {

    private static final String SHADOW = "__ASOF";

    /** Tables that are history themselves, never part of what a sheet shows. */
    private static final Set<String> SKIP = Set.of("FLYWAY_SCHEMA_HISTORY", "SHEET_STATE", "SHEET_SNAPSHOT");

    /** A table kept per sheet: its stored columns and how its rows of one sheet are found. */
    private record Kept(String table, String columns, String scope) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;

    /** In the order a parent comes before the rows that reference it. */
    private volatile List<Kept> kept = List.of();

    public SheetSnapshots(JdbcTemplate jdbc, SheetClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    /** Finds the tables kept per sheet and makes their shadow tables (DDL, so once on boot, outside any change). */
    @EventListener(ApplicationReadyEvent.class)
    public synchronized void prepare() {
        List<Kept> found = jdbc.execute((ConnectionCallback<List<Kept>>) (con) -> {
            DatabaseMetaData meta = con.getMetaData();
            Map<String, List<String>> columns = new LinkedHashMap<>();
            try (ResultSet rs = meta.getColumns(null, "PUBLIC", "%", "%")) {
                while (rs.next()) {
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useIsLatest } from '../../query/useIsLatest';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { isHeld, peopleKey, peoplePath, personActionKey } from './people';
import type { Person } from './people';

function HoldHeader() {
  return (
    <>
      <th>Hold</th>
      <th>Holds</th>
      <th />
    </>
  );
}

// Whether the person has any hold, each of their holds, and the dates and button that add one (a blank from-date
// is the sheet's today; a blank to-date never ends). Their OPEN claims dated within a hold count in no live total,
// unless bound by a statement; their other claims still do. A hold ends on its to-date.
function PersonHold({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const hold = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person[]>(byUser(`${peoplePath(sheet)}/${person.id}/hold`, user), dates),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated);
      setFrom('');
      setTo('');
    },
  });
  const act = useSubmitOnce(hold);
  const latest = useIsLatest(personActionKey(sheet, person.id), hold.submittedAt);

  return (
    <>
      <td data-testid="person-hold">{isHeld(person) ? 'yes' : 'no'}</td>
      <td>
        {person.holds.map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? ''}
          </div>
        ))}
      </td>
      <td>
        <input
          data-testid="person-hold-from"
          type="text"
          placeholder="from yyyy-mm-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          data-testid="person-hold-to"
          type="text"
          placeholder="to yyyy-mm-dd"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => act({ from: from.trim(), to: to.trim() })}
        >
          Hold
        </button>
        {hold.isError && latest && (
          <span data-testid="person-error" role="alert">
            {' '}That hold was refused.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 40, Component: HoldHeader }),
  PersonColumns.fill({ order: 40, Component: PersonHold }),
];
import { useQuery } from '@tanstack/react-query';
import { useReadScope } from '../../query/live';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** One of a person's grades, in force from its from-date (yyyy-MM-dd; null when it applies from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

// grade is the one in force on the sheet's today; grades are every one recorded, by from-date.
// retiredFrom is null unless the person is retired; once set, they count as retired whatever the date.
/** One of a person's holds: from its from-date to its to-date, both included (yyyy-MM-dd; to is null when it never ends). */
export type Hold = { from: string; to: string | null };

// holds are every one added, in that order; their OPEN claims dated within a hold count in no live total, unless
// bound by a statement; their other claims still do.
export type Person = {
  id: number;
  name: string;
  grade: Grade;
  version: number;
  retiredFrom: string | null;
  holds: Hold[];
  grades: GradeFrom[];
  /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
  terms: number | null;
  /** Whether the sheet's today is on or after retiredFrom: from then their OPEN and PENDING claims, unless bound by a
   *  statement, count in no live total. */
  retiredNow: boolean;
  /** The person's contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** Whether their name or an alias is already a name or alias on another sheet of the sheet's tree (its ancestors
   *  and descendants): every edit of them is refused until it renames them out of the clash. */
  clashing: boolean;
};

/** The person's grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(person: Person, date: string): Grade | undefined {
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** Whether the person has any hold. */
export const isHeld = (p: Person) => p.holds.length > 0;

/** Whether a date (yyyy-MM-dd) is within one of the person's holds. */
export const heldOn = (p: Person, date: string) =>
  p.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));

export const isRetired = (p: Person) => p.retiredFrom !== null;

/** Whether a claim of the person's dated on the day (yyyy-MM-dd), open and not bound by a statement, is kept out of
 *  every live total: it is dated within one of their holds, or their retirement date is reached. */
export const setAsideOn = (p: Person, date: string) => p.retiredNow || heldOn(p, date);

export const peopleKey = (sheet: string) => ['people', sheet] as const;

/** The mutation key every action on a person's row shares, so the row shows only its latest action's refusal. */
export const personActionKey = (sheet: string, person: number) => ['person-action', sheet, person] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in the order they were added. */
export function usePeople(sheet: string) {
  const read = useReadScope(peopleKey(sheet));
  return useQuery({
    queryKey: read.key,
    queryFn: () => read.get<Person[]>(peoplePath(sheet)),
  });
}

/** Whether retired people are listed: off until turned on, and kept in the URL so loading a sheet leaves it be. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
              : 'A person needs a name not already on the sheet or its tree (and, when clashing, a new name and aliases that no longer clash), a grade of A, B or C, a from-date that is a valid date or blank, terms that are a whole number of days or blank, and a contact not already another person\'s on the sheet.'}
          </span>
        )}
      </form>
      <QuickAdd sheet={sheet} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Contact</th>
            <th>Clashing</th>
            <PersonColumnHeaders.Slot sheet={sheet} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-terms">{termsText(p)}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
              <PersonColumns.Slot sheet={sheet} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 10, Component: People });

